// ─── Produk Komersial — Batch 3 — Produk (SKU) Registry ──────────────────────
    // PK-R02C: Produk/SKU individual milik satu Seri, untuk 5 kategori Batch 3
    // (Acidifier, Buffer, Toxin Binder, Yeast, Herbal Komersial). Level paling
    // bawah dari hierarki Kategori → Brand → Seri → Produk. Setiap produk WAJIB
    // memiliki UUID, nama, brand, seri, kategori, kemasan, deskripsi, dan status
    // aktif — sesuai kontrak PK-R02C (sama dengan PK-R02A/PK-R02B).
    //
    // Data ini diproyeksikan ke PRODUK_KOMERSIAL_LIST generik
    // (produkKomersialData.ts) lewat produkKomersialBatch3Adapter.ts agar otomatis
    // terhitung pada Ringkasan/Dashboard dan otomatis tersedia untuk dipilih
    // Formula lewat readiness layer (formulaProdukKomersialData.ts) — tanpa
    // mengubah struktur Formula, Master Pakan, Stok, atau Livestock.

    export interface ProdukKomersialBatch3Item {
    uuid: string;
    seriId: string; // UUID → ProdukKomersialBatch3Seri.uuid
    brandId: string; // UUID → ProdukKomersialBatch3Brand.uuid
    kategoriId: string; // UUID → KATEGORI_UUID
    kategoriSlug: string; // routing only
    slug: string;
    namaProduk: string;
    kemasan: string;
    deskripsi: string;
    statusAktif: boolean;
    updatedAt: string;
    // ── PK-R03A.3F: Field detail Konsentrat-quality (optional, Acidifier & Buffer) ──
    komposisi?: string[];
    kandunganAktif?: string;
    fungsiProduk?: string[];
    faseTernak?: string;
    caraPenggunaan?: string;
    dosis?: string;
    penyimpanan?: string;
    hargaReferensi?: number;        // IDR per kemasan
    catatanPenggunaan?: string;
    // ── PK-R03A.3H: Field detail Konsentrat-quality (Herbal Komersial) ──
    hargaPerKg?: number;
    }

