    /** Daftar produk milik satu seri (UUID). */
    export function getBatch3ProdukBySeriId(seriId: string): ProdukKomersialBatch3Item[] {
    return PK_BATCH3_PRODUK_LIST.filter(p => p.seriId === seriId);
    }

    /** Lookup satu produk via seriId + produkSlug (routing). */
    export function getBatch3ProdukBySlug(seriId: string, produkSlug: string): ProdukKomersialBatch3Item | undefined {
    return PK_BATCH3_PRODUK_LIST.find(p => p.seriId === seriId && p.slug === produkSlug);
    }

    /** Lookup produk via UUID. */
    export function getBatch3ProdukByUUID(uuid: string): ProdukKomersialBatch3Item | undefined {
    return PK_BATCH3_PRODUK_LIST.find(p => p.uuid === uuid);
    }

    /** Jumlah total produk pada satu kategori (slug). */
    export function getBatch3JumlahProdukByKategoriSlug(kategoriSlug: string): number {
    return PK_BATCH3_PRODUK_LIST.filter(p => p.kategoriSlug === kategoriSlug).length;
    }
    